edits:
            G1 Y{printer['gcode_macro PRINTER_PARAM'].clear_y_position} F9000
            {% if printer.extruder.can_extrude %}                  
                G91
                G1  E{e} F300
                G90
            {% endif %}
            {% if printer.save_variables.variables.box_count >= 1 and printer.save_variables.variables.enable_box == 1 %} 
            G1 Y{printer['gcode_macro PRINTER_PARAM'].clear_y_position} F9000
            _QIDI_RESUME_PRIME E={e}
            {% if printer.save_variables.variables.box_count >= 1 and printer.save_variables.variables.enable_box == 1 %} 
    {% endif %}


[gcode_macro RESUME]
    {% endif %}


# Evaluate extrusion readiness at execution time, after RESUME_PRINT M109.
[gcode_macro _QIDI_RESUME_PRIME]
gcode:
    {% set e = params.E|default(150)|int %}
    {% if printer.extruder.can_extrude %}
        G91
        G1  E{e} F300
        G90
    {% endif %}

[gcode_macro RESUME]
